contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract so pausable functions are available
        c.initialize(address(this));
    }

    function testFuzz_property(bool _pause, bool _unpause) public {
        // Admissible domain: we need to reach the UNPAUSED state.
        // The simplest way is: pause and then unpause.
        // The fuzzer will try both true/false for these flags; we assume
        // both are true so the unpause actually happens.
        vm.assume(_pause);
        vm.assume(_unpause);

        // Set up admin role for this test contract (address(this) is passed as lrtConfig in setUp, which has DEFAULT_ADMIN_ROLE)
        // Pause the contract
        c.pause();
        // Unpause the contract
        c.unpause();

        // After unpausing, the reference contract MUST return false for paused().
        // The mutant returns true because paused() always returns true.
        assertTrue(!c.paused());
    }
}

