pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool doPause) public {
        // Initialize the contract with a valid lrtConfig address that supports required roles.
        // We use the InvMutTest itself as a mock that supports IAccessControl.
        c.initialize(address(this));

        // InvMutTest must have DEFAULT_ADMIN_ROLE (0x00) to call unpause and MANAGER to call pause.
        // We grant these roles to ourselves via _setupRole in the test contract.
        // But the test contract must implement IAccessControl. We implement the minimal interface.

        if (doPause) {
            // Pause via the external pause() function (requires MANAGER role).
            c.pause();
        } else {
            // Unpause via the external unpause() function (requires DEFAULT_ADMIN_ROLE).
            c.unpause();
        }

        bool actualPaused = c.paused();
        // The property: after pause(), paused() must return true; after unpause(), paused() must return false.
        // The bug returns false regardless.
        // Since doPause is fuzzed, the fuzzer will try both true and false.
        assertTrue(actualPaused == doPause);
    }

    // Minimal IAccessControl implementation to allow pause/unpause role checks.
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;

    function hasRole(bytes32 role, address account) external view returns (bool) {
        if (role == LRTConstants.MANAGER && account == address(this)) return true;
        if (role == DEFAULT_ADMIN_ROLE && account == address(this)) return true;
        return false;
    }

    function getRoleAdmin(bytes32) external pure returns (bytes32) { return DEFAULT_ADMIN_ROLE; }
    function grantRole(bytes32, address) external pure {}
    function revokeRole(bytes32, address) external pure {}
    function renounceRole(bytes32, address) external pure {}
}

