import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lrtConfig, uint256 pauseSeq) public {
        vm.assume(lrtConfig != address(0));
        vm.assume(lrtConfig.code.length > 0);
        c.initialize(lrtConfig);

        // Simulate pause/unpause actions by admin/manager roles via low-level calls
        bool paused = c.paused();
        bool actuallyPaused = paused;

        // Perform a sequence of pause/unpause based on bits of pauseSeq (max 8 operations)
        for (uint256 i = 0; i < 8; i++) {
            if ((pauseSeq >> i) & 1 == 1) {
                // Try to pause (will revert if not manager, but that's fine)
                try c.pause() { actuallyPaused = true; } catch {}
            } else {
                // Try to unpause (will revert if not admin, but that's fine)
                try c.unpause() { actuallyPaused = false; } catch {}
            }
        }

        // After all attempts, paused() must reflect the actual paused state
        bool observedPaused = c.paused();
        assertTrue(observedPaused == actuallyPaused);
    }
}

