contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address manager, address newConfig) public {
        vm.assume(manager != address(0));
        vm.assume(newConfig != address(0));
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
