contract DummyConfig {
    function hasRole(bytes32 role, address account) external view returns (bool) {
        // Minimal implementation: returns true only for msg.sender (the test contract)
        // This allows the test contract to act as admin for initialization purposes.
        if (account == address(0xaAaAaAaaAaAaAaaAaAaaaAaAaAAAaaAaaAaAaAA)) {
            return true;
